<?php require_once __DIR__.'/config/config.php';$s=$pdo->prepare('SELECT * FROM products WHERE id=? AND active=1');$s->execute([(int)($_GET['id']??0)]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Product not found');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$qty=max(1,(int)$_POST['qty']);if($qty>$p['stock']){$error='Requested quantity is not available.';}else{$_SESSION['cart'][$p['id']]=['qty'=>$qty];go('cart.php');}}$pageTitle=$p['name'].' | WatchesError';require 'includes/header.php';?><section class="section"><div class="container"><div class="row g-5 align-items-center"><div class="col-md-6"><img class="img-fluid rounded-4" src="<?=e($p['image_url'])?>" alt="<?=e($p['name'])?>"></div><div class="col-md-6"><div class="eyebrow"><?=e($p['category'])?> Collection</div><h1 style="font-family:'Playfair Display'"><?=e($p['name'])?></h1><h3 class="price"><?=money($p['sale_price']?:$p['price'])?></h3><p class="text-secondary"><?=nl2br(e($p['description']))?></p><p><?= (int)$p['stock']>0?'Available stock: '.(int)$p['stock']:'Currently unavailable'?></p><?php if(!empty($error)):?><p class="text-danger"><?=e($error)?></p><?php endif;?><form method="post"><?=csrf_field()?><label class="form-label">Quantity</label><input class="form-control mb-3" type="number" name="qty" min="1" max="<?=max(1,(int)$p['stock'])?>" value="1" style="max-width:120px" <?=!$p['stock']?'disabled':''?>><button class="btn btn-gold" <?=!$p['stock']?'disabled':''?>>Add to Cart</button></form></div></div></div></section><?php require 'includes/footer.php';?>